-- ALTER TABLE subcommands and constraint attributes
ALTER TABLE t
	OWNER TO admin;

ALTER TABLE t
	ALTER COLUMN a TYPE bigint USING a::bigint;

ALTER TABLE ONLY parted
	ADD CONSTRAINT c CHECK (a > 0) NOT VALID;

ALTER TABLE m
	ATTACH PARTITION p1 FOR VALUES FROM (1) TO (10);

ALTER TABLE m
	ATTACH PARTITION pdef DEFAULT;

ALTER TABLE m
	DETACH PARTITION p1 CONCURRENTLY;

ALTER TABLE t
	VALIDATE CONSTRAINT c;

ALTER INDEX i
	ALTER COLUMN 2 SET STATISTICS 100;

ALTER TABLE t
	ALTER COLUMN a SET STORAGE EXTERNAL;

ALTER TABLE t
	ALTER COLUMN a SET COMPRESSION lz4;

ALTER TABLE t
	ALTER COLUMN id DROP IDENTITY IF EXISTS;

ALTER TABLE t
	SET LOGGED;

ALTER TABLE t
	SET (fillfactor = 70, autovacuum_enabled = false);

ALTER TABLE t
	RESET (fillfactor);

ALTER TABLE t
	INHERIT parent,
	NO INHERIT other_parent;

ALTER TABLE t
	CLUSTER ON idx;

ALTER TABLE t
	SET WITHOUT CLUSTER;

ALTER TABLE t
	SET TABLESPACE fast;

ALTER TABLE t
	SET ACCESS METHOD heap2;

ALTER TABLE t
	ENABLE ALWAYS TRIGGER tr;

ALTER TABLE t
	DISABLE TRIGGER ALL;

ALTER TABLE t
	ENABLE RULE r;

ALTER TABLE t
	REPLICA IDENTITY USING INDEX idx;

ALTER TABLE t
	REPLICA IDENTITY FULL;

ALTER TABLE t
	FORCE ROW LEVEL SECURITY;

ALTER TABLE t
	ADD PRIMARY KEY USING INDEX pkidx;

CREATE TABLE fk_pair (
	a int,
	b int,
	FOREIGN KEY (a, b) REFERENCES p (x, y) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE deferred_unique (
	id int UNIQUE DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE nulls_unique (
	id int,
	a int,
	UNIQUE NULLS NOT DISTINCT (id) INCLUDE (a)
);

CREATE TABLE reservations (
	room int,
	during tsrange,
	EXCLUDE USING gist (room WITH =, during WITH &&) WHERE (room > 0)
);

